import React from 'react';

interface ReportViewerProps {
  tenantId: string;
  startDate: Date;
  endDate: Date;
}

const ReportViewer: React.FC<ReportViewerProps> = ({ tenantId, startDate, endDate }) => {
  return (
    <div>
      <p>Tenant: {tenantId}</p>
      <p>Start: {startDate.toDateString()}</p>
      <p>End: {endDate.toDateString()}</p>
      {/* Your report rendering logic */}
    </div>
  );
};

export default ReportViewer;
